"""Module for common utility functions and classes"""
import json
from datetime import datetime, timezone
from typing import Any
from uuid import UUID


class CustomJsonEncoder(json.JSONEncoder):
    """JSON encoder which can serialize datetime and UUID objects"""

    def default(self, obj: Any) -> Any:
        """
        Handles encoding UUID and datetime in a custom manner.
        :param obj: Data to encode
        :return: Encoded data
        """
        if isinstance(obj, UUID):
            return str(obj)
        elif isinstance(obj, datetime):
            date_obj: datetime = obj
            if date_obj.tzinfo:
                date_obj = date_obj.astimezone(timezone.utc)  # Always in UTC
            return date_obj.strftime("%Y-%m-%dT%H:%M:%S.%fZ")

        return super().default(obj)


def to_json(data: dict) -> str:
    """
    Convert dict to JSON string.
    :param data: Data to convert
    :return: JSON string
    """
    return json.dumps(data, cls=CustomJsonEncoder)


def merge_dicts(target: dict, source: dict) -> None:
    """
    Merge two dictionaries recursively.

    Merge strategy:
      - If the key is not in the target, add it.
      - If the key is in the target:
          - If the source type is dict, merge the dicts.
          - If the source type is list, extend the target lists.
          - Otherwise, overwrite the target parameter with the source value.

    :param target: The dictionary to merge into.
    :param source: The dictionary to merge from.
    """
    for key, value in source.items():
        if key not in target:
            target[key] = value
        else:
            if isinstance(value, dict):
                merge_dicts(target[key], value)
            elif isinstance(value, list):
                target[key].extend(value)
            else:
                target[key] = value
